          <tr><td>House wrap, siding and trim</td><td class="num">$2,500</td><td class="num">$5,000</td><td>Cedar and metal panels at the high end</td></tr>
          <tr><td>Insulation</td><td class="num">$2,000</td><td class="num">$4,500</td><td>Closed-cell spray foam costs most</td></tr>
          <tr><td>Electrical (panel, wire, fixtures, inlet)</td><td class="num">$2,500</td><td class="num">$4,500</td><td>Includes licensed help or inspection where required</td></tr>
