          <tr><td>Interior walls and ceiling</td><td class="num">$2,000</td><td class="num">$4,000</td><td>Tongue-and-groove pine, plywood or shiplap</td></tr>
          <tr><td>Flooring</td><td class="num">$1,000</td><td class="num">$2,000</td><td>Luxury vinyl plank vs hardwood</td></tr>
